<?php
declare(strict_types=1);
require_once dirname($_SERVER['DOCUMENT_ROOT']).'/backyard_private/app/bootstrap.php';
require_once dirname($_SERVER['DOCUMENT_ROOT']).'/backyard_private/app/points.php';
require_once dirname($_SERVER['DOCUMENT_ROOT']).'/backyard_private/app/jokers.php';
$u=requireUser();$error='';$setupError='';$uid=(int)$u['id'];

if($_SERVER['REQUEST_METHOD']==='POST')try {
    verifyCsrf();
    if(($_POST['action']??'')!=='accept')throw new RuntimeException('Unbekannte Aktion.');
    missionAccept((int)($_POST['mission_id']??0),$uid);
    redirect('competition.php?accepted=1#missions');
}catch(Throwable $e) {
    $error=$e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'Die Mission konnte gerade nicht angenommen werden.';
}
if(isset($_GET['mission_error']))$error='Die Mission konnte gerade nicht angenommen werden.';

$score=null;$timeline=['labels'=>[],'series'=>[],'weeks'=>[]];$missions=[];$jokers=[];
try {
    missionRefreshRunner($uid);
    jokerRefreshAll();
    $missions=missionList($uid);
    $jokers=jokerList($uid);
    $score=teamPointsBoard();
    $timeline=teamPointsTimeline($score);
}catch(PDOException $e) {
    $setupError='Challenge, Missionen oder Joker sind noch nicht vollständig eingerichtet. Bitte die Datenbankmigrationen ausführen.';
}
$mine=array_values(array_filter($missions,static fn(array $m):bool=>$m['own_entry']!==null));
$available=array_values(array_filter($missions,static fn(array $m):bool=>(bool)$m['can_accept']));
$other=array_values(array_filter($missions,static fn(array $m):bool=>$m['own_entry']===null&&!$m['can_accept']));
$myJokers=array_values(array_filter($jokers,static fn(array $j):bool=>(bool)$j['is_own']));
$teamJokers=array_values(array_filter($jokers,static fn(array $j):bool=>!(bool)$j['is_own']));
$activeMyJokers=array_values(array_filter($myJokers,static fn(array $j):bool=>$j['status']==='active'));
$historyMyJokers=array_values(array_filter($myJokers,static fn(array $j):bool=>$j['status']!=='active'));
$activeTeamJokers=array_values(array_filter($teamJokers,static fn(array $j):bool=>$j['status']==='active'));
$historyTeamJokers=array_values(array_filter($teamJokers,static fn(array $j):bool=>$j['status']!=='active'));
$myPoints=$score?($score['board'][strtolower((string)$u['username'])]??null):null;$myRank=null;
if($score)foreach($score['ranking'] as $i=>$person)if(strtolower((string)$person['username'])===strtolower((string)$u['username'])){$myRank=$i+1;break;}
$allLoops=$score?array_sum(array_column($score['board'],'loops')):0;
$finishedWeeks=$score?count(array_filter($score['history'],static fn(array $week):bool=>$week['complete'])):0;
$currentWeek=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('o-\\WW');
