<?php if($myPoints):?><div class="competition-total"><div><small>DEIN GESAMTSTAND</small><strong><?=h((string)$myPoints['points'])?> Punkte</strong><p><?=h((string)$myPoints['challenge_points'])?> Challenge · +<?=h((string)$myPoints['mission_points'])?> Missionen · −<?=h((string)$myPoints['joker_penalties'])?> Joker</p></div><?php if($myRank!==null):?><div class="competition-total-rank"><small>PLATZ</small><strong>#<?=h((string)$myRank)?></strong></div><?php endif;?></div><?php else:?><p class="competition-empty">Das Punktekonto wird für die Teamläufer Tim, Jonas und Noah geführt.</p><?php endif;?>
<div class="competition-scoreboard"><?php foreach($score['ranking'] as $i=>$person):?><article class="competition-score"><span class="name" style="color:<?=h($person['color'])?>">#<?=h((string)($i+1))?> · <?=h($person['name'])?></span><strong><?=h((string)$person['points'])?> Punkte</strong><div class="parts"><?=h((string)$person['challenge_points'])?> Challenge · +<?=h((string)$person['mission_points'])?> Missionen · −<?=h((string)$person['joker_penalties'])?> Joker</div></article><?php endforeach;?></div></section>

<section class="panel competition-panel" id="trend"><p class="eyebrow">PUNKTE ÜBER ZEIT</p><h2>Kontostand im Verlauf</h2><p class="competition-panel-intro">Kumulierte Punkte pro Kalenderwoche. Challengepunkte zählen zur jeweiligen KW; Missionen und Joker zum Zeitpunkt ihres Abschlusses.</p>
