<div class="competition-subsection"><h3>Meine Missionen</h3><div class="mission-list"><?php if(!$mine):?><p class="competition-empty">Du hast aktuell keine Mission angenommen.</p><?php endif;?><?php foreach($mine as $mission):$missionAudience='runner';require __DIR__.'/partials/mission-card.php';endforeach;?></div></div>
<div class="competition-subsection"><h3>Verfügbare Missionen</h3><div class="mission-list"><?php if(!$available):?><p class="competition-empty">Aktuell wartet keine Mission auf dich.</p><?php endif;?><?php foreach($available as $mission):$missionAudience='runner';require __DIR__.'/partials/mission-card.php';endforeach;?></div></div>
<?php if($other):?><details class="competition-week"><summary>Team und Missionsverlauf</summary><div class="competition-subsection"><div class="mission-list"><?php foreach($other as $mission):$missionAudience='runner';require __DIR__.'/partials/mission-card.php';endforeach;?></div></div></details><?php endif;?></section>

<section class="panel competition-panel" id="jokers"><p class="eyebrow">HERAUSFORDERUNG</p><h2>Joker</h2><p class="competition-panel-intro">Ein Joker prüft ein Wochenziel oder einen Lauf. Erfolg schützt deine Gesamtpunktzahl; Scheitern zieht drei Punkte ab.</p>
