document.addEventListener('DOMContentLoaded',()=>{const data=JSON.parse(document.getElementById('points-history-data')?.textContent||'{}');const canvas=document.getElementById('points-history-chart');if(!canvas)return;if(!window.Chart){const fallback=document.getElementById('points-chart-fallback');if(fallback)fallback.hidden=false;return;}new Chart(canvas,{type:'line',data:{labels:data.labels,datasets:Object.values(data.series||{}).map(r=>({label:r.name,data:r.values,borderColor:r.color,backgroundColor:r.color,pointRadius:0,pointHoverRadius:4,borderWidth:3,tension:.22}))},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:'#d6e0e8',usePointStyle:true,boxWidth:8}},tooltip:{callbacks:{label:ctx=>`${ctx.dataset.label}: ${ctx.parsed.y} Punkte`}}},scales:{x:{ticks:{color:'#9dadbd',maxTicksLimit:12},grid:{color:'rgba(157,173,189,.12)'}},y:{title:{display:true,text:'Punkte',color:'#9dadbd'},ticks:{color:'#9dadbd'},grid:{color:'rgba(157,173,189,.12)'}}}}});});
